import{_ as a,c as o,o as i,a0 as t}from"./chunks/framework.oTSD2LDJ.js";const u=JSON.parse('{"title":"UniDeskWindow","description":"","frontmatter":{"title":"UniDeskWindow","editLink":true},"headers":[],"relativePath":"controls-reference/UniDeskWindow.md","filePath":"zh/controls-reference/UniDeskWindow.md"}'),r={name:"controls-reference/UniDeskWindow.md"};function s(n,e,l,p,d,c){return i(),o("div",null,e[0]||(e[0]=[t('<h1 id="unideskwindow-类型" tabindex="-1">UniDeskWindow 类型 <a class="header-anchor" href="#unideskwindow-类型" aria-label="Permalink to &quot;UniDeskWindow 类型&quot;">​</a></h1><p>Uniquenium 的基础窗口控件，在 <code>QtQuick.Window</code> 之上封装了无边框、亚克力模糊、自定义标题栏（AppBar）、内置提示条等能力，是所有应用窗口（设置窗口、组件管理窗口、页面管理窗口等）的基类。</p><table tabindex="0"><thead><tr><th>控件类型</th><th>可视化控件（Control）</th></tr></thead><tbody><tr><td>源代码文件路径</td><td><code>UniDesk/Controls/UniDeskWindow.qml</code></td></tr><tr><td>继承</td><td>QtQuick Window</td></tr></tbody></table><h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2><h3 id="default-property-alias-contentdata" tabindex="-1"><code>default property alias contentData</code> <a class="header-anchor" href="#default-property-alias-contentdata" aria-label="Permalink to &quot;`default property alias contentData`&quot;">​</a></h3><p>默认属性，指向窗口主内容区域 <code>layout_content.data</code>，使用 <code>UniDeskWindow { Text { ... } }</code> 时子 Item 会自动进入内容区。</p><h3 id="property-string-windowicon" tabindex="-1"><code>property string windowIcon</code> <a class="header-anchor" href="#property-string-windowicon" aria-label="Permalink to &quot;`property string windowIcon`&quot;">​</a></h3><p>窗口图标（显示在 AppBar 左侧）。</p><h3 id="property-int-launchmode-unideskwindowtype-standard" tabindex="-1"><code>property int launchMode: UniDeskWindowType.Standard</code> <a class="header-anchor" href="#property-int-launchmode-unideskwindowtype-standard" aria-label="Permalink to &quot;`property int launchMode: UniDeskWindowType.Standard`&quot;">​</a></h3><p>窗口启动模式（由 <code>UniDeskWindowType</code> 枚举定义）。</p><h3 id="property-var-argument" tabindex="-1"><code>property var argument: ({})</code> <a class="header-anchor" href="#property-var-argument" aria-label="Permalink to &quot;`property var argument: ({})`&quot;">​</a></h3><p>窗口初始化时传入的参数对象，会在 <code>Component.onCompleted</code> 中通过 <code>initArgument(argument)</code> 信号传递给子类。</p><h3 id="property-var-background" tabindex="-1"><code>property var background</code> <a class="header-anchor" href="#property-var-background" aria-label="Permalink to &quot;`property var background`&quot;">​</a></h3><p>窗口背景，默认为内部的 <code>com_background</code> 组件（包含壁纸图 + 亚克力模糊）。</p><h3 id="property-bool-fixsize-false" tabindex="-1"><code>property bool fixSize: false</code> <a class="header-anchor" href="#property-bool-fixsize-false" aria-label="Permalink to &quot;`property bool fixSize: false`&quot;">​</a></h3><p>是否固定窗口大小。开启后窗口不可拖拽缩放，最大化/最小化按钮也会被禁用。</p><h3 id="property-bool-fitsappbarwindows-false" tabindex="-1"><code>property bool fitsAppBarWindows: false</code> <a class="header-anchor" href="#property-bool-fitsappbarwindows-false" aria-label="Permalink to &quot;`property bool fitsAppBarWindows: false`&quot;">​</a></h3><p>是否让 AppBar 区域与内容区域对齐（当 AppBar 嵌入系统标题栏时使用）。</p><h3 id="property-var-tintopacity" tabindex="-1"><code>property var tintOpacity</code> <a class="header-anchor" href="#property-var-tintopacity" aria-label="Permalink to &quot;`property var tintOpacity`&quot;">​</a></h3><p>亚克力背景的不透明度，深色模式默认 <code>0.50</code>，浅色模式默认 <code>0.75</code>。</p><h3 id="property-int-blurradius-80" tabindex="-1"><code>property int blurRadius: 80</code> <a class="header-anchor" href="#property-int-blurradius-80" aria-label="Permalink to &quot;`property int blurRadius: 80`&quot;">​</a></h3><p>亚克力模糊半径。</p><h3 id="property-var-windowvisibility" tabindex="-1"><code>property var windowVisibility</code> <a class="header-anchor" href="#property-var-windowvisibility" aria-label="Permalink to &quot;`property var windowVisibility`&quot;">​</a></h3><p>窗口 <code>visibility</code> 的属性别名（用于 QML 绑定）。</p><h3 id="property-alias-effect-frameless-effect" tabindex="-1"><code>property alias effect: frameless.effect</code> <a class="header-anchor" href="#property-alias-effect-frameless-effect" aria-label="Permalink to &quot;`property alias effect: frameless.effect`&quot;">​</a></h3><p>当前无边框窗口所使用的特效（指向 <code>UniDeskFrameless.effect</code>）。</p><h3 id="readonly-property-alias-effective-frameless-effective" tabindex="-1"><code>readonly property alias effective: frameless.effective</code> <a class="header-anchor" href="#readonly-property-alias-effective-frameless-effective" aria-label="Permalink to &quot;`readonly property alias effective: frameless.effective`&quot;">​</a></h3><p>当前特效是否生效（只读）。</p><h3 id="readonly-property-alias-availableeffects-frameless-availableeffects" tabindex="-1"><code>readonly property alias availableEffects: frameless.availableEffects</code> <a class="header-anchor" href="#readonly-property-alias-availableeffects-frameless-availableeffects" aria-label="Permalink to &quot;`readonly property alias availableEffects: frameless.availableEffects`&quot;">​</a></h3><p>可用的特效列表（只读）。</p><h3 id="property-item-appbar" tabindex="-1"><code>property Item appBar</code> <a class="header-anchor" href="#property-item-appbar" aria-label="Permalink to &quot;`property Item appBar`&quot;">​</a></h3><p>窗口自定义标题栏（默认创建一个 <code>UniDeskAppBar</code> 实例，会跟随窗口标题、图标和按钮显示状态自动更新）。</p><h3 id="property-color-backgroundcolor" tabindex="-1"><code>property color backgroundColor</code> <a class="header-anchor" href="#property-color-backgroundcolor" aria-label="Permalink to &quot;`property color backgroundColor`&quot;">​</a></h3><p>窗口背景色，根据主题（深色/浅色）、窗口激活状态、是否启用亚克力效果自动计算。</p><h3 id="property-bool-staytop-false" tabindex="-1"><code>property bool stayTop: false</code> <a class="header-anchor" href="#property-bool-staytop-false" aria-label="Permalink to &quot;`property bool stayTop: false`&quot;">​</a></h3><p>窗口是否置顶。</p><h3 id="property-bool-showdark-false" tabindex="-1"><code>property bool showDark: false</code> <a class="header-anchor" href="#property-bool-showdark-false" aria-label="Permalink to &quot;`property bool showDark: false`&quot;">​</a></h3><p>是否强制窗口进入深色模式（影响 AppBar 按钮与边框色）。</p><h3 id="property-bool-showclose-true" tabindex="-1"><code>property bool showClose: true</code> <a class="header-anchor" href="#property-bool-showclose-true" aria-label="Permalink to &quot;`property bool showClose: true`&quot;">​</a></h3><p>是否显示关闭按钮。</p><h3 id="property-bool-showminimize-true" tabindex="-1"><code>property bool showMinimize: true</code> <a class="header-anchor" href="#property-bool-showminimize-true" aria-label="Permalink to &quot;`property bool showMinimize: true`&quot;">​</a></h3><p>是否显示最小化按钮。</p><h3 id="property-bool-showmaximize-true" tabindex="-1"><code>property bool showMaximize: true</code> <a class="header-anchor" href="#property-bool-showmaximize-true" aria-label="Permalink to &quot;`property bool showMaximize: true`&quot;">​</a></h3><p>是否显示最大化/还原按钮。</p><h3 id="property-bool-showstaytop-false" tabindex="-1"><code>property bool showStayTop: false</code> <a class="header-anchor" href="#property-bool-showstaytop-false" aria-label="Permalink to &quot;`property bool showStayTop: false`&quot;">​</a></h3><p>是否显示置顶按钮。</p><h3 id="property-bool-automaximize-false" tabindex="-1"><code>property bool autoMaximize: false</code> <a class="header-anchor" href="#property-bool-automaximize-false" aria-label="Permalink to &quot;`property bool autoMaximize: false`&quot;">​</a></h3><p>窗口创建时是否自动最大化。</p><h3 id="property-bool-autovisible-true" tabindex="-1"><code>property bool autoVisible: true</code> <a class="header-anchor" href="#property-bool-autovisible-true" aria-label="Permalink to &quot;`property bool autoVisible: true`&quot;">​</a></h3><p>窗口创建后是否自动调用 <code>show()</code>。</p><h3 id="property-bool-autocenter-true" tabindex="-1"><code>property bool autoCenter: true</code> <a class="header-anchor" href="#property-bool-autocenter-true" aria-label="Permalink to &quot;`property bool autoCenter: true`&quot;">​</a></h3><p>窗口创建后是否自动移动到桌面中心。</p><h3 id="property-bool-autodestroy-true" tabindex="-1"><code>property bool autoDestroy: true</code> <a class="header-anchor" href="#property-bool-autodestroy-true" aria-label="Permalink to &quot;`property bool autoDestroy: true`&quot;">​</a></h3><p>窗口关闭时是否自动销毁（若为 <code>false</code>，则将 <code>visibility</code> 置为 <code>Hidden</code>）。</p><h3 id="property-bool-usesystemappbar" tabindex="-1"><code>property bool useSystemAppBar</code> <a class="header-anchor" href="#property-bool-usesystemappbar" aria-label="Permalink to &quot;`property bool useSystemAppBar`&quot;">​</a></h3><p>是否使用系统标题栏（由子类在 <code>Component.onCompleted</code> 中赋值，默认 <code>false</code>）。</p><h3 id="property-int-margins-0" tabindex="-1"><code>property int __margins: 0</code> <a class="header-anchor" href="#property-int-margins-0" aria-label="Permalink to &quot;`property int __margins: 0`&quot;">​</a></h3><p>窗口内容区域与窗口边框之间的内边距。</p><h3 id="property-color-resizebordercolor" tabindex="-1"><code>property color resizeBorderColor</code> <a class="header-anchor" href="#property-color-resizebordercolor" aria-label="Permalink to &quot;`property color resizeBorderColor`&quot;">​</a></h3><p>窗口边框颜色，依据主题与窗口激活状态自动计算。</p><h3 id="property-int-resizeborderwidth-1" tabindex="-1"><code>property int resizeBorderWidth: 1</code> <a class="header-anchor" href="#property-int-resizeborderwidth-1" aria-label="Permalink to &quot;`property int resizeBorderWidth: 1`&quot;">​</a></h3><p>窗口边框宽度，同时也是拖拽边框的命中区域宽度。</p><h3 id="property-var-closelistener" tabindex="-1"><code>property var closeListener</code> <a class="header-anchor" href="#property-var-closelistener" aria-label="Permalink to &quot;`property var closeListener`&quot;">​</a></h3><p>关闭事件回调，签名为 <code>function(event)</code>；当 <code>autoDestroy=false</code> 时会在这里拦截关闭事件，将窗口隐藏而非销毁。</p><h3 id="property-bool-hideshadow-false" tabindex="-1"><code>property bool _hideShadow: false</code> <a class="header-anchor" href="#property-bool-hideshadow-false" aria-label="Permalink to &quot;`property bool _hideShadow: false`&quot;">​</a></h3><p>是否隐藏窗口阴影。</p><h2 id="信号" tabindex="-1">信号 <a class="header-anchor" href="#信号" aria-label="Permalink to &quot;信号&quot;">​</a></h2><h3 id="signal-focusout" tabindex="-1"><code>signal focusOut()</code> <a class="header-anchor" href="#signal-focusout" aria-label="Permalink to &quot;`signal focusOut()`&quot;">​</a></h3><p>窗口失去焦点时由内部 <code>UniDeskFrameless</code> 转发。</p><h3 id="signal-initargument-var-argument" tabindex="-1"><code>signal initArgument(var argument)</code> <a class="header-anchor" href="#signal-initargument-var-argument" aria-label="Permalink to &quot;`signal initArgument(var argument)`&quot;">​</a></h3><p>窗口完成初始化时发出，参数为构造时传入的 <code>argument</code>，供子类重写以获取启动参数。</p><h3 id="signal-lazyload" tabindex="-1"><code>signal lazyLoad()</code> <a class="header-anchor" href="#signal-lazyload" aria-label="Permalink to &quot;`signal lazyLoad()`&quot;">​</a></h3><p>窗口首次显示时发出（懒加载触发），用于延迟加载重型资源。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="function-movewindowtodesktopcenter" tabindex="-1"><code>function moveWindowToDesktopCenter()</code> <a class="header-anchor" href="#function-movewindowtodesktopcenter" aria-label="Permalink to &quot;`function moveWindowToDesktopCenter()`&quot;">​</a></h3><p>将窗口移动到当前桌面可用区域的正中央。</p><h3 id="function-fixwindowsize" tabindex="-1"><code>function fixWindowSize()</code> <a class="header-anchor" href="#function-fixwindowsize" aria-label="Permalink to &quot;`function fixWindowSize()`&quot;">​</a></h3><p>根据 <code>fixSize</code> 属性锁定窗口最大/最小尺寸。</p><h3 id="function-setresult-data" tabindex="-1"><code>function setResult(data)</code> <a class="header-anchor" href="#function-setresult-data" aria-label="Permalink to &quot;`function setResult(data)`&quot;">​</a></h3><p>向窗口注册器（<code>_windowRegister</code>）返回结果。</p><h3 id="function-showmaximized-function-showminimized-function-shownormal" tabindex="-1"><code>function showMaximized()</code> / <code>function showMinimized()</code> / <code>function showNormal()</code> <a class="header-anchor" href="#function-showmaximized-function-showminimized-function-shownormal" aria-label="Permalink to &quot;`function showMaximized()` / `function showMinimized()` / `function showNormal()`&quot;">​</a></h3><p>显式地将窗口切换为最大化 / 最小化 / 普通状态。</p><h3 id="function-sethittestvisible-val" tabindex="-1"><code>function setHitTestVisible(val)</code> <a class="header-anchor" href="#function-sethittestvisible-val" aria-label="Permalink to &quot;`function setHitTestVisible(val)`&quot;">​</a></h3><p>设置窗口是否接收鼠标命中测试（透传开关）。</p><h3 id="function-deletelater" tabindex="-1"><code>function deleteLater()</code> <a class="header-anchor" href="#function-deletelater" aria-label="Permalink to &quot;`function deleteLater()`&quot;">​</a></h3><p>延迟销毁窗口（最终调用 <code>UniDeskUtils.deleteLater</code>）。</p><h3 id="function-containeritem" tabindex="-1"><code>function containerItem()</code> <a class="header-anchor" href="#function-containeritem" aria-label="Permalink to &quot;`function containerItem()`&quot;">​</a></h3><p>返回窗口的根容器 Item（<code>layout_container</code>），便于将子组件动态挂载到窗口内。</p><h3 id="function-showactivate" tabindex="-1"><code>function showActivate()</code> <a class="header-anchor" href="#function-showactivate" aria-label="Permalink to &quot;`function showActivate()`&quot;">​</a></h3><p>若窗口已可见则激活（<code>requestActivate</code>），否则调用 <code>show()</code> 显示。</p><h3 id="function-showsuccess-text-duration-moremsg-function-showinfo-function-showwarning-function-showerror" tabindex="-1"><code>function showSuccess(text, duration, moremsg)</code> / <code>function showInfo(...)</code> / <code>function showWarning(...)</code> / <code>function showError(...)</code> <a class="header-anchor" href="#function-showsuccess-text-duration-moremsg-function-showinfo-function-showwarning-function-showerror" aria-label="Permalink to &quot;`function showSuccess(text, duration, moremsg)` / `function showInfo(...)` / `function showWarning(...)` / `function showError(...)`&quot;">​</a></h3><p>通过内置 <code>UniDeskInfoBar</code> 显示临时提示信息。</p><h3 id="function-clearallinfo" tabindex="-1"><code>function clearAllInfo()</code> <a class="header-anchor" href="#function-clearallinfo" aria-label="Permalink to &quot;`function clearAllInfo()`&quot;">​</a></h3><p>清除窗口内所有正在显示的提示信息。</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><div class="language-qml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">qml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UniDeskWindow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的窗口&quot;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    windowIcon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;qrc:/icons/app.png&quot;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    argument</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { userId: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    autoCenter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    autoMaximize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    stayTop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    showDark</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: UniDeskGlobals.isLight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    onInitArgument</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;收到启动参数:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, argument)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Column</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">        anchors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">centerIn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: parent</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        Text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello Uniquenium&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><ul><li><code>UniDeskWindow</code> 配合 <code>UniDeskFrameless</code> 实现真正的无边框窗口，所有拖拽、命中测试、亚克力效果均由后者提供。</li><li>窗口背景默认使用当前系统壁纸（<code>UniDeskTools.get_system_wallpaper()</code>）并叠加 <code>UniDeskAcrylic</code> 产生毛玻璃效果。</li><li>在 Wayland 或软件渲染模式下会自动回退为纯色背景（<code>UniDeskUtils.isSoftware()</code>）。</li><li>关闭行为由 <code>closeListener</code> 控制：<code>autoDestroy=true</code> 时直接销毁窗口；<code>autoDestroy=false</code> 时只隐藏窗口，常用于需要常驻的工具窗口。</li></ul>',98)]))}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
